import{_ as a,o as d,c as l,a2 as e}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"三、保障方案","description":"根据客户的面谈信息，制定个性化的保障方案。","frontmatter":{},"headers":[],"relativePath":"副业/保险展业/03-保障方案.md","filePath":"副业/保险展业/03-保障方案.md","lastUpdated":1793113268000}'),n={name:"副业/保险展业/03-保障方案.md"};function i(r,t,s,h,o,p){return d(),l("div",null,[...t[0]||(t[0]=[e(`<h1 id="三、保障方案" tabindex="-1">三、保障方案 <a class="header-anchor" href="#三、保障方案" aria-label="Permalink to &quot;三、保障方案&quot;">​</a></h1><p>根据客户的面谈信息，制定个性化的保障方案。</p><h2 id="_1-方案设计原则" tabindex="-1">1. 方案设计原则 <a class="header-anchor" href="#_1-方案设计原则" aria-label="Permalink to &quot;1. 方案设计原则&quot;">​</a></h2><ul><li><strong>先保障后储蓄</strong>：优先覆盖重疾、医疗、意外等风险</li><li><strong>先大人后小孩/老人</strong>：家庭经济支柱先保</li><li><strong>量入为出</strong>：保费不超过家庭年收入的 10-15%</li><li><strong>动态调整</strong>：随着家庭收入变化逐步完善</li></ul><h2 id="_2-常见家庭保障方案" tabindex="-1">2. 常见家庭保障方案 <a class="header-anchor" href="#_2-常见家庭保障方案" aria-label="Permalink to &quot;2. 常见家庭保障方案&quot;">​</a></h2><h3 id="单身人士-25-35岁" tabindex="-1">单身人士（25-35岁） <a class="header-anchor" href="#单身人士-25-35岁" aria-label="Permalink to &quot;单身人士（25-35岁）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>险种</th><th>作用</th><th>建议保额</th><th>备注</th></tr></thead><tbody><tr><td>百万医疗险</td><td>报销大额医疗费</td><td>200万+</td><td>首选</td></tr><tr><td>重疾险</td><td>一次性给付，弥补收入损失</td><td>30-50万</td><td>长期险</td></tr><tr><td>意外险</td><td>意外身故/伤残/医疗</td><td>50-100万</td><td>一年一买</td></tr><tr><td>定期寿险</td><td>特定时期身故保障</td><td>50-100万</td><td>有房贷/父母需赡养加配</td></tr></tbody></table><h3 id="三口之家-孩子0-10岁" tabindex="-1">三口之家（孩子0-10岁） <a class="header-anchor" href="#三口之家-孩子0-10岁" aria-label="Permalink to &quot;三口之家（孩子0-10岁）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>险种</th><th>大人</th><th>孩子</th></tr></thead><tbody><tr><td>百万医疗险</td><td>✅</td><td>✅</td></tr><tr><td>重疾险</td><td>✅ 50万+</td><td>✅ 50万</td></tr><tr><td>意外险</td><td>✅</td><td>✅</td></tr><tr><td>定期寿险</td><td>✅（经济支柱重点）</td><td>❌</td></tr><tr><td>教育金</td><td>❌</td><td>✅（有余力）</td></tr></tbody></table><h3 id="_40岁-家庭顶梁柱" tabindex="-1">40岁+家庭顶梁柱 <a class="header-anchor" href="#_40岁-家庭顶梁柱" aria-label="Permalink to &quot;40岁+家庭顶梁柱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>险种</th><th>重点</th></tr></thead><tbody><tr><td>百万医疗险</td><td>✅ 必配</td></tr><tr><td>重疾险</td><td>✅ 重点，防收入中断</td></tr><tr><td>定期寿险</td><td>✅ 保障家庭责任期</td></tr><tr><td>养老险</td><td>✅ 开始规划</td></tr><tr><td>意外险</td><td>✅ 高保额</td></tr></tbody></table><h2 id="_3-方案呈现" tabindex="-1">3. 方案呈现 <a class="header-anchor" href="#_3-方案呈现" aria-label="Permalink to &quot;3. 方案呈现&quot;">​</a></h2><h3 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一、家庭保障概览</span></span>
<span class="line"><span>二、现有保障分析（已有哪些保障）</span></span>
<span class="line"><span>三、保障缺口分析（哪些还没覆盖）</span></span>
<span class="line"><span>四、推荐方案</span></span>
<span class="line"><span>   1. 险种A — 年缴 XXXX 元</span></span>
<span class="line"><span>      保障内容：...</span></span>
<span class="line"><span>      适用理由：...</span></span>
<span class="line"><span>   2. 险种B — 年缴 XXXX 元</span></span>
<span class="line"><span>      ...</span></span>
<span class="line"><span>五、年缴总保费：XXXX 元（占家庭年收入 X%）</span></span>
<span class="line"><span>六、备注与说明</span></span></code></pre></div><h3 id="讲解原则" tabindex="-1">讲解原则 <a class="header-anchor" href="#讲解原则" aria-label="Permalink to &quot;讲解原则&quot;">​</a></h3><ul><li>先讲风险，再说解决方案（不要先说产品）</li><li>用客户自己的话描述需求，展示你听懂了</li><li>解释每款险种&quot;解决什么问题&quot;</li><li>强调&quot;这个方案是根据您的情况定制的&quot;</li></ul><h2 id="_4-方案调整" tabindex="-1">4. 方案调整 <a class="header-anchor" href="#_4-方案调整" aria-label="Permalink to &quot;4. 方案调整&quot;">​</a></h2><h3 id="客户嫌贵" tabindex="-1">客户嫌贵 <a class="header-anchor" href="#客户嫌贵" aria-label="Permalink to &quot;客户嫌贵&quot;">​</a></h3><ul><li>降低保额，拉长缴费期</li><li>暂时去掉储蓄型，换成消费型</li><li>分步实施：先买医疗险+意外险，以后加保</li></ul><h3 id="客户觉得不够" tabindex="-1">客户觉得不够 <a class="header-anchor" href="#客户觉得不够" aria-label="Permalink to &quot;客户觉得不够&quot;">​</a></h3><ul><li>加保终身寿险/增额终身寿</li><li>提高重疾保额</li><li>加教育金/养老险</li></ul><h3 id="客户有异议产品" tabindex="-1">客户有异议产品 <a class="header-anchor" href="#客户有异议产品" aria-label="Permalink to &quot;客户有异议产品&quot;">​</a></h3><ul><li>准备好替代方案</li><li>用对比表展示不同产品的优劣势</li><li>专业客观，不要贬低竞品</li></ul><h2 id="_5-注意事项" tabindex="-1">5. 注意事项 <a class="header-anchor" href="#_5-注意事项" aria-label="Permalink to &quot;5. 注意事项&quot;">​</a></h2><ul><li>❌ 不要直接给产品链接让客户自己看</li><li>❌ 不要只给一个方案，让客户没得选</li><li>❌ 不要隐瞒保费或夸大保障</li><li>✅ 每个险种都要讲清楚&quot;保什么、不保什么&quot;</li><li>✅ 方案要因人而异，不要套模板发给所有人</li></ul>`,25)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
